(function($){'use strict';function initEventTypeSelector(){var select=document.querySelector('select[data-cal-link]');if(!select)return;var calLink=document.getElementById('calLink');if(calLink&&select.value){var opt=select.querySelector('option[value="'+select.value+'"]');if(opt){calLink.value=opt.getAttribute('data-booking-url')||''}}
select.addEventListener('change',function(){var val=this.value;var url='';if(val){var opt=this.querySelector('option[value="'+val+'"]');if(opt){url=opt.getAttribute('data-booking-url')||''}}
if(calLink){calLink.value=url;calLink.dispatchEvent(new Event('input',{bubbles:!0}))}})}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initEventTypeSelector)}else{initEventTypeSelector()}})(jQuery)